AgentWebView::AgentWebView(wxWindow*                  parent,
                           const ShellTheme&          theme,
                           Workspace::IWorkspace&     workspace,
                           Agent::ProjectPersistence& persistence,
                           Agent::AgentAvailability   availability,
                           Agent::AgentServicePtr      agent,
                           Agent::AgentSetupServicePtr setup,
                           AgentPageMode               mode)
    : wxPanel(parent, wxID_ANY)
    , m_theme(theme)
    , m_host(std::make_unique<Agent::AgentHost>(workspace, persistence, availability, GUI_App::dark_mode(),
                                                std::move(agent), std::move(setup)))
    , m_handshake_timer(this, kHandshakeTimerId)
{
    m_host->set_mcp_cli_runner([this](const std::vector<std::string>& arguments, Agent::AgentHost::McpCliDone done) {
        start_mcp_setup_command(this, arguments, [complete = std::move(done)](McpSetupResult result) {
            complete(result.success, std::move(result.diagnostic));
        });
    });
    // The host resolves which file this is; it only lacks a way to show it.
    // Deferred rather than called inline: this runs inside the web view's
    // script-message handler, and handing the file manager the main thread
    // before that handler returns is a way to stall the view's own message
    // pump. Nothing here depends on the reveal having happened.
    m_host->set_reveal_path_handler([this](const std::string& path) {
        CallAfter([path] { desktop_open_any_folder(path); });
    });
    // The composer's + menu asks for one kind of file; the host names the
    // extensions and the dialog filters to them, upper case too, since some
    // platforms match the wildcard case-sensitively. Deferred like the reveal
    // above: a modal dialog must not run inside the script-message handler.
    m_host->set_file_picker([this](const Agent::AgentHost::FilePickerRequest& request,
                                   std::function<void(std::vector<std::string>)> done) {
        CallAfter([this, request, done = std::move(done)] {
            wxString patterns;
            for (const std::string& extension : request.extensions) {
                const wxString lower = wxString::FromUTF8(extension);
                patterns += (patterns.empty() ? "" : ";") + ("*." + lower) + ";*." + lower.Upper();
            }
            const wxString wildcard = wxString::FromUTF8(request.description) + " (" + patterns + ")|" + patterns;
            wxFileDialog dialog(this, _L("Attach files"), wxEmptyString, wxEmptyString, wildcard,
                                wxFD_OPEN | wxFD_FILE_MUST_EXIST | wxFD_MULTIPLE);
            std::vector<std::string> chosen;
            if (dialog.ShowModal() == wxID_OK) {
                wxArrayString paths;
                dialog.GetPaths(paths);
                for (const wxString& path : paths)
                    chosen.push_back(path.ToUTF8().data());
            }

