import json,re,glob,os
pat=re.compile(r'(thinking row|Thinking row|default thinking|thinking default|newChatThinking|new_chat_thinking|Thinking.{0,40}New chats start|New chats start with.{0,200}[Tt]hinking)',re.S)
for f in sorted(glob.glob('*.jsonl'),key=os.path.getmtime):
    hits=[]
    for line in open(f,errors='ignore'):
        try: d=json.loads(line)
        except: continue
        if d.get('type')!='user': continue
        c=d.get('message',{}).get('content')
        texts=[c] if isinstance(c,str) else [x.get('text','') for x in c if isinstance(x,dict) and x.get('type')=='text'] if isinstance(c,list) else []
        for t in texts:
            if pat.search(t) and len(t)<4000: hits.append((d.get('timestamp','')[:16],t[:600].replace('\n',' ')))
    for h in hits[:4]: print(f[:8],h[0],h[1],'\n')
EOF

